(function(){
  "use strict";
  const $ = id => document.getElementById(id);
  const { coins, pct, nf0, esc, icon, wikiLink } = window.SBUI;
  const norm = s => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");

  let DB = null, products = null, cur = null, recipeIdx = 0, sel = -1, hits = [];
  const state = { sortKey:"treeProfit", sortDir:-1 };
  // Recipes live in data/recipes.json (generated by tools/build_recipes.py)
  let dbError = false;
  fetch("data/recipes.json").then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); }).then(j => {
    DB = j;
    DB.search = Object.keys(DB.recipes).map(id => ({id, n: name(id), k: norm(name(id) + " " + id)}));
    renderAll();
  }).catch(() => {
    dbError = true;
    $("cbody").innerHTML = `<tr><td colspan="8" class="empty">Recepty se nenačetly. Soubor data/recipes.json musí ležet vedle index.html a stránka musí běžet přes web (GitHub Pages nebo lokální server), ne otevřená přímo z disku.</td></tr>`;
  });
  function db(){ return DB; }
  function name(id){
    if (DB && DB.names[id]) return DB.names[id];
    return id.toLowerCase().split(/[_:]/).filter(Boolean).map(w => w[0].toUpperCase()+w.slice(1)).join(" ");
  }
  const tax = () => (parseFloat(($("tax")||{}).value) || 1.25)/100;

  function prices(id){
    const p = products && products[id];
    if (!p) return null;
    const offers = p.buy_summary || [], orders = p.sell_summary || [], qs = p.quick_status || {};
    return {
      order: orders.length ? orders[0].pricePerUnit + 0.1 : null,   // you place a buy order
      insta: offers.length ? offers[0].pricePerUnit : null,         // you insta-buy
      offer: offers.length ? offers[0].pricePerUnit - 0.1 : null,   // you place a sell offer
      instaSell: orders.length ? orders[0].pricePerUnit : null,     // you insta-sell
      weekly: Math.min(qs.buyMovingWeek||0, qs.sellMovingWeek||0)
    };
  }
  function ingredients(rec){
    const m = {};
    rec.g.forEach(c => { if (c) m[c[0]] = (m[c[0]]||0) + c[1]; });
    return m;
  }
  function craftCost(rec){
    let order = 0, insta = 0; const missing = [];
    for (const [id, q] of Object.entries(ingredients(rec))){
      const pr = prices(id);
      if (!pr || pr.order == null || pr.insta == null){ missing.push(id); continue; }
      order += pr.order*q; insta += pr.insta*q;
    }
    return {order, insta, missing};
  }

  // ---------- whole craft tree: cheapest way to get one unit of an item ----------
  // Returns {unit, mode:"buy"|"craft", ri (recipe index), buy (bazaar price or null)} or null.
  function bestUnit(id, memo, stack){
    if (memo.has(id)) return memo.get(id);
    const pr = prices(id);
    const buy = pr && pr.order != null ? pr.order : null;
    let best = buy != null ? {unit:buy, mode:"buy", buy} : null;
    const r = DB.recipes[id];
    if (r && !stack.has(id) && stack.size < 8){
      stack.add(id);
      r.r.forEach((rec, ri) => {
        let sum = 0;
        for (const [ing, q] of Object.entries(ingredients(rec))){
          const b = bestUnit(ing, memo, stack);
          if (!b) return;
          sum += b.unit*q;
        }
        const unit = sum/(rec.c||1);
        if (unit > 0 && (!best || unit < best.unit*0.999)) best = {unit, mode:"craft", ri, buy};
      });
      stack.delete(id);
    }
    memo.set(id, best);
    return best;
  }
  function buildNode(id, qty, memo, depth){
    const b = bestUnit(id, memo, new Set());
    const node = {id, qty, b, children:[]};
    if (b && b.mode === "craft" && depth < 8){
      const rec = DB.recipes[id].r[b.ri];
      node.crafts = Math.ceil(qty/(rec.c||1));
      for (const [ing, q] of Object.entries(ingredients(rec))) node.children.push(buildNode(ing, q*node.crafts, memo, depth+1));
    }
    return node;
  }
  function collect(node, list, missing){
    if (!node.b){ missing.add(node.id); return; }
    if (node.b.mode === "buy"){
      const e = list.get(node.id) || {id:node.id, qty:0, unit:node.b.unit};
      e.qty += node.qty; list.set(node.id, e); return;
    }
    node.children.forEach(c => collect(c, list, missing));
  }
  function treeCost(rec, memo){
    let sum = 0;
    for (const [ing, q] of Object.entries(ingredients(rec))){
      const b = bestUnit(ing, memo, new Set([cur]));
      if (!b) return null;
      sum += b.unit*q;
    }
    return sum;
  }

  function reqHtml(r){
    if (r.q) return `<span class="req">Potřebná kolekce: <b>${esc(r.q)}</b></span>`;
    if (r.s){
      const m = String(r.s).match(/^([A-Z]+)_(\d+)$/);
      const SL = {ZOMBIE:"Revenant Horror", SPIDER:"Tarantula Broodfather", WOLF:"Sven Packmaster", EMAN:"Voidgloom Seraph (Enderman)", BLAZE:"Inferno Demonlord", VAMPIRE:"Riftstalker Bloodfiend"};
      const t = m ? `${SL[m[1]] || m[1]} ${m[2]}` : r.s;
      return `<span class="req">Potřebný slayer: <b>${esc(t)}</b></span>`;
    }
    return `<span class="req none">Recept nemá požadavek na kolekci</span>`;
  }

  // ---------- search ----------
  function search(q){
    q = norm(q.trim());
    if (q.length < 2) return [];
    const starts = [], has = [];
    for (const e of db().search){
      const i = e.k.indexOf(q);
      if (i === 0 || e.k.includes(" " + q)) starts.push(e); else if (i > 0) has.push(e);
    }
    const onBz = e => products && products[e.id] ? 0 : 1;
    const by = (a,b) => onBz(a)-onBz(b) || a.n.length-b.n.length;
    return starts.sort(by).concat(has.sort(by)).slice(0, 8);
  }
  function showResults(){
    const ul = $("cresults"), inp = $("cq");
    if (!hits.length){ ul.hidden = true; inp.setAttribute("aria-expanded","false"); return; }
    ul.innerHTML = hits.map((h,i) => {
      const r = DB.recipes[h.id];
      const tag = r.q ? esc(r.q) : (products && products[h.id] ? "na bazaaru" : "");
      return `<li role="option" id="cr-${i}" data-i="${i}" aria-selected="${i===sel}"><span>${icon(h.n, 20)}${esc(h.n)}</span><small>${tag}</small></li>`;
    }).join("");
    ul.hidden = false; inp.setAttribute("aria-expanded","true");
    inp.setAttribute("aria-activedescendant", sel >= 0 ? "cr-"+sel : "");
  }
  function pick(id){
    cur = id; recipeIdx = 0; hits = []; sel = -1;
    $("cq").value = name(id);
    showResults(); renderCard();
    $("ccard").scrollIntoView({block:"nearest", behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"});
  }
  $("cq").addEventListener("input", e => { if (!DB) return; hits = search(e.target.value); sel = hits.length ? 0 : -1; showResults(); });
  $("cq").addEventListener("keydown", e => {
    if (e.key === "ArrowDown" && hits.length){ e.preventDefault(); sel = (sel+1) % hits.length; showResults(); }
    else if (e.key === "ArrowUp" && hits.length){ e.preventDefault(); sel = (sel-1+hits.length) % hits.length; showResults(); }
    else if (e.key === "Enter" && hits[sel]){ e.preventDefault(); pick(hits[sel].id); }
    else if (e.key === "Escape"){ hits = []; showResults(); }
  });
  $("cresults").addEventListener("mousedown", e => {
    const li = e.target.closest("li[data-i]"); if (!li) return;
    e.preventDefault(); pick(hits[+li.dataset.i].id);
  });
  $("cq").addEventListener("blur", () => setTimeout(() => { hits = []; showResults(); }, 120));

  // ---------- item card ----------
  function treeHtml(n){
    const nm = name(n.id);
    const head = `${icon(nm, 18)}<span class="nm">${esc(nm)}</span> × ${nf0.format(n.qty)}`;
    if (!n.b) return `<li><span class="leaf">${head}<span class="how miss">není na bazaaru</span></span></li>`;
    if (n.b.mode === "buy") return `<li><span class="leaf">${head}<span class="how">koupit za ${coins(n.b.unit*n.qty)}</span></span></li>`;
    const save = n.b.buy != null ? `, ušetříš ${coins((n.b.buy - n.b.unit)*n.qty)}` : ", koupit se nedá";
    return `<li><details open><summary>${head}<span class="how craft">vycraftit ${n.crafts}×${save}</span></summary><ul>${n.children.map(treeHtml).join("")}</ul></details></li>`;
  }
  function renderCard(){
    const card = $("ccard");
    if (!cur){ card.hidden = true; return; }
    const r = db().recipes[cur];
    const rec = r.r[Math.min(recipeIdx, r.r.length-1)];
    const count = rec.c || 1;
    const t = tax();
    const curName = name(cur);
    let html = `<div class="titlerow">${icon(curName, 48)}<h2>${esc(curName)}</h2>${wikiLink(curName)}</div>${reqHtml(r)}`;
    if (r.r.length > 1){
      html += `<div class="rswitch" role="group" aria-label="Recepty">` + r.r.map((x,i) =>
        `<button type="button" data-rec="${i}" aria-pressed="${i===recipeIdx}">Recept ${i+1}${x.c && x.c>1 ? ` (${x.c} ks)` : ""}</button>`).join("") + `</div>`;
    }
    const cell = c => {
      if (!c) return `<div class="cell empty" aria-hidden="true"></div>`;
      const n = name(c[0]), nm = esc(n), inner = `${icon(n, 32)}<span class="cn">${nm}</span><span class="q">${c[1]}</span>`;
      return DB.recipes[c[0]]
        ? `<button type="button" class="cell" data-open="${esc(c[0])}" title="Otevřít recept: ${nm}">${inner}</button>`
        : `<div class="cell" title="${nm}">${inner}</div>`;
    };
    html += `<div class="cgrid-wrap"><div class="cgrid" role="img" aria-label="Rozložení receptu">${rec.g.map(cell).join("")}</div>
      <span class="arrow" aria-hidden="true">→</span>
      <div class="cell out" title="${esc(curName)}">${icon(curName, 44)}<span class="cn">${esc(curName)}</span><span class="q">${count}×</span></div></div>`;

    if (!products){
      card.innerHTML = html + `<p class="note">Čekám na ceny z bazaaru…</p>`; card.hidden = false; return;
    }
    const memo = new Map();
    const ing = ingredients(rec);
    const rows = Object.entries(ing).map(([id,q]) => {
      const pr = prices(id), n = name(id);
      const nm = DB.recipes[id] ? `<button type="button" class="linkbtn" data-open="${esc(id)}">${esc(n)}</button>` : esc(n);
      const b = bestUnit(id, memo, new Set([cur]));
      let sub = `<span class="muted">–</span>`;
      if (b && b.mode === "craft") sub = b.buy != null ? `<span class="cheaper">craft za ${coins(b.unit*q)}, ušetříš ${coins((b.buy-b.unit)*q)}</span>` : `craft za ${coins(b.unit*q)}`;
      else if (DB.recipes[id] && b) sub = `<span class="muted">koupit je levnější</span>`;
      if (!pr || pr.order == null){
        return `<tr><td>${icon(n)}${nm}</td><td>${nf0.format(q)}</td><td colspan="3" class="muted">není na bazaaru (NPC, drop nebo aukce)</td><td>${sub}</td></tr>`;
      }
      return `<tr><td>${icon(n)}${nm}</td><td>${nf0.format(q)}</td><td>${coins(pr.order)}</td><td>${coins(pr.order*q)}</td><td>${coins(pr.insta*q)}</td><td>${sub}</td></tr>`;
    }).join("");
    html += `<div class="tablebox ingr" style="margin-top:18px"><table>
      <thead><tr><th>Surovina</th><th>Množství</th><th>Za kus (buy order)</th><th>Celkem (buy ordery)</th><th>Celkem (okamžitě)</th><th>Vycraftit sám?</th></tr></thead>
      <tbody>${rows}</tbody></table></div>`;

    const c = craftCost(rec), out = prices(cur);
    const nodes = Object.entries(ing).map(([id,q]) => buildNode(id, q, memo, 1));
    const list = new Map(), missing = new Set();
    nodes.forEach(n => collect(n, list, missing));
    const treeTotal = [...list.values()].reduce((a,e) => a + e.qty*e.unit, 0);
    const treeOk = missing.size === 0;

    const box = (k, v, cls, s) => `<div><div class="k">${k}</div><div class="v ${cls||""}">${v}</div>${s ? `<div class="s">${s}</div>` : ""}</div>`;
    const signed = v => (v >= 0 ? "+" : "") + coins(v);
    let sum = box("Cena craftu přes buy ordery", coins(c.order), "", c.missing.length ? "bez surovin mimo bazaar" : "suroviny koupené hotové")
            + box("Cena přes celý strom", treeOk ? coins(treeTotal) : "neúplná", treeOk && treeTotal < c.order - 0.5 ? "pos" : "",
                  treeOk ? (treeTotal < c.order - 0.5 ? `o ${coins(c.order - treeTotal)} levnější` : "stejná, nic se nevyplatí craftit") : "některé suroviny nejsou na bazaaru")
            + box("Cena craftu okamžitě", coins(c.insta), "", "insta-buy všech surovin");
    if (out && out.offer != null){
      const rev = out.offer*(1-t)*count, revI = out.instaSell*(1-t)*count;
      const prof = rev - c.order, profT = rev - treeTotal, profI = revI - c.insta;
      sum += box("Prodej přes sell offer", coins(rev), "", `po dani, ${count} ks`)
           + box("Zisk na craft", signed(prof), prof >= 0 ? "pos" : "neg", `ordery → sell offer, marže ${pct(prof/c.order)}`);
      if (treeOk) sum += box("Zisk se stromem", signed(profT), profT >= 0 ? "pos" : "neg", `marže ${pct(profT/treeTotal)}`);
      sum += box("Zisk při okamžitém obchodu", signed(profI), profI >= 0 ? "pos" : "neg", "insta-buy → insta-sell");
    } else {
      sum += box("Prodej", "mimo bazaar", "", "porovnej cenu craftu s aukcemi (lowest BIN)");
    }
    html += `<div class="summary">${sum}</div>`;
    if (c.missing.length){
      html += `<p class="note">Ceny nezahrnují: ${c.missing.map(id => esc(name(id))).join(", ")}. Tyhle suroviny se na bazaaru neprodávají.</p>`;
    }

    html += `<h4 class="subsec">Celý strom craftu</h4>
      <p class="note" style="margin-top:0">U každé suroviny vybírá levnější cestu: koupit hotovou přes buy order, nebo ji vycraftit z levnějších surovin (až 8 úrovní).</p>
      <ul class="tree">${nodes.map(treeHtml).join("")}</ul>`;
    const shop = [...list.values()].sort((a,b) => b.qty*b.unit - a.qty*a.unit);
    html += `<h4 class="subsec">Nákupní seznam pro celý strom</h4>
      <div class="tablebox ingr" style="margin-top:8px"><table>
      <thead><tr><th>Koupit</th><th>Množství</th><th>Za kus (buy order)</th><th>Celkem</th></tr></thead>
      <tbody>${shop.map(e => { const n = name(e.id); return `<tr><td>${icon(n)}${esc(n)}</td><td>${nf0.format(e.qty)}</td><td>${coins(e.unit)}</td><td>${coins(e.qty*e.unit)}</td></tr>`; }).join("")}
      ${missing.size ? `<tr><td colspan="4" class="muted">Mimo bazaar sežeň: ${[...missing].map(id => esc(name(id))).join(", ")}</td></tr>` : ""}
      </tbody></table></div>`;
    card.innerHTML = html;
    card.hidden = false;
  }
  $("ccard").addEventListener("click", e => {
    const o = e.target.closest("[data-open]");
    if (o){ pick(o.dataset.open); return; }
    const b = e.target.closest("[data-rec]");
    if (b){ recipeIdx = +b.dataset.rec; renderCard(); }
  });

  // ---------- best crafts ----------
  const cols = [
    {key:"name", label:"Item"}, {key:null, label:"Kolekce"}, {key:"cost", label:"Cena craftu"},
    {key:"rev", label:"Prodej (po dani)"}, {key:"profit", label:"Zisk / craft"}, {key:"treeProfit", label:"Zisk se stromem"},
    {key:"margin", label:"Marže"}, {key:"weekly", label:"Objem / týden"}
  ];
  function renderHead(){
    $("chead").innerHTML = cols.map(c => {
      if (!c.key) return `<th scope="col">${c.label}</th>`;
      const s = state.sortKey === c.key;
      return `<th scope="col"${s ? ` aria-sort="${state.sortDir<0?"descending":"ascending"}"` : ""}><button type="button" data-key="${c.key}">${c.label}${s ? (state.sortDir<0?" ▾":" ▴") : ""}</button></th>`;
    }).join("");
  }
  function renderBest(){
    renderHead();
    if (!products) return;
    const t = tax(), out = [], memo = new Map();
    for (const id in db().recipes){
      const pr = prices(id);
      if (!pr || pr.offer == null || pr.weekly < 50000) continue;
      let best = null;
      DB.recipes[id].r.forEach(rec => {
        const c = craftCost(rec);
        if (c.missing.length || !(c.order > 0)) return;
        let tc = 0;
        for (const [ing, q] of Object.entries(ingredients(rec))){ const b = bestUnit(ing, memo, new Set([id])); tc += b ? b.unit*q : Infinity; }
        tc = Math.min(tc, c.order);
        const rev = pr.offer*(1-t)*(rec.c||1), profit = rev - c.order, treeProfit = rev - tc;
        if (!best || treeProfit > best.treeProfit) best = {id, name:name(id), cost:c.order, rev, profit, treeProfit, margin:treeProfit/tc, weekly:pr.weekly, q:DB.recipes[id].q};
      });
      if (best && best.treeProfit > 0) out.push(best);
    }
    const k = state.sortKey, d = state.sortDir;
    out.sort((a,b) => k === "name" ? d*a.name.localeCompare(b.name,"cs") : d*(a[k]-b[k]));
    $("cbody").innerHTML = out.length ? out.slice(0,60).map(r => `<tr class="row" tabindex="0" data-id="${esc(r.id)}">
        <td>${icon(r.name)}<span class="item">${esc(r.name)}</span>${r.margin > 0.4 ? '<span class="tag risk" title="Neobvykle vysoká marže, ověř ceny ve hře">riziko</span>' : ""}</td>
        <td>${r.q ? esc(r.q) : '<span class="muted">–</span>'}</td>
        <td>${coins(r.cost)}</td><td>${coins(r.rev)}</td>
        <td class="${r.profit > 0 ? "pos" : "muted"}">${coins(r.profit)}</td><td class="pos">${coins(r.treeProfit)}</td>
        <td>${pct(r.margin)}</td><td>${coins(r.weekly)}</td></tr>`).join("")
      : `<tr><td colspan="8" class="empty">Teď se žádný craft nevyplácí.</td></tr>`;
  }
  $("chead").addEventListener("click", e => {
    const b = e.target.closest("button[data-key]"); if (!b) return;
    if (state.sortKey === b.dataset.key) state.sortDir *= -1; else { state.sortKey = b.dataset.key; state.sortDir = b.dataset.key === "name" ? 1 : -1; }
    renderBest();
  });
  $("cbody").addEventListener("click", e => { const tr = e.target.closest("tr.row"); if (tr) pick(tr.dataset.id); });
  $("cbody").addEventListener("keydown", e => {
    if (e.key !== "Enter" && e.key !== " ") return;
    const tr = e.target.closest("tr.row"); if (tr){ e.preventDefault(); pick(tr.dataset.id); }
  });

  function renderAll(){
    if ($("tab-craft").hidden) return;
    if (!DB){ if (!dbError) $("cbody").innerHTML = `<tr><td colspan="8" class="empty">Načítám recepty…</td></tr>`; return; }
    renderBest(); renderCard();
  }
  window.addEventListener("bazaar-updated", e => { products = e.detail; renderAll(); });
  if (window.SB_STATE && window.SB_STATE.products) products = window.SB_STATE.products;
  window.addEventListener("tab-shown", e => { if (e.detail === "craft") renderAll(); });
  $("tax").addEventListener("change", renderAll);
})();
